<?php declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$user=require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('dashboard');verify_csrf();if(!$user['is_email_verified']){$recent=db()->prepare('SELECT 1 FROM verification_tokens WHERE user_id=? AND used_at IS NULL AND created_at>DATE_SUB(NOW(),INTERVAL 1 MINUTE)');$recent->execute([$user['id']]);if($recent->fetch()){flash('error','Please wait one minute before requesting another email.');}else{db()->prepare('DELETE FROM verification_tokens WHERE user_id=? AND used_at IS NULL')->execute([$user['id']]);issue_verification($user);flash('success','A new verification email has been prepared.');}}redirect('dashboard');
